    '年滿 65 歲且設籍臺北市的長輩，可申請敬老卡，搭乘公車、捷運享有優惠。': 'Elders aged 65 or older who are registered in Taipei City can apply for a Senior Citizen Card and get discounts on buses and the MRT.',
    '臺北市政府社會局': 'Department of Social Welfare, Taipei City Government',
    '申辦說明': 'About this service',
    '這次要幫您申請「敬老卡」。辦好之後，搭公車、捷運都有優惠。': 'We will help you apply for the Senior Citizen Card. Once it is issued, you get discounts on buses and the MRT.',
    '先口頭確認長輩年滿 65 歲、戶籍在臺北市。確認後按「下一步」。': 'First, check by talking that the elder is 65 or older and registered in Taipei City. Then tap "Next step".',
    '確認身分': 'Confirm identity',
    '接下來需要您的基本資料。手機會一項一項問您，您同意才會提供。': 'Next we need your basic information. Your phone will ask about each item, and it is provided only if you agree.',
    '依序按「請長輩授權」。請長輩自己看清楚手機畫面再按，不要替長輩按。': 'Tap "Ask elder to authorize" in order. Ask the elder to read the phone screen carefully and tap by themselves. Do not tap for them.',
