    '身分證字號': 'ID number',
    '核對戶籍與申請資格，避免重複申請': 'Used to check household registration and eligibility, and to avoid duplicate applications',
    '身分證字號可以拿來辦很多事，請確認是您自己要申請': 'An ID number can be used for many things. Make sure you are the one applying',
    '市府人員不會要求您把身分證字號唸給陌生人聽': 'City staff will never ask you to read your ID number to strangers',
