    '臺北市中山區健康服務中心辦理「長者流感疫苗預約」需要': 'To handle "Senior Flu Vaccine Appointment", Zhongshan District Health Center, Taipei City needs',
    '電話': 'Phone',
    '里長': 'Village chief',
    '免費健康檢查｜65 歲以上長者報名': 'Free Health Check-up | Sign-up for Ages 65 and Over',
    '中山區健康服務中心為 65 歲以上長輩提供免費健康檢查，檢查約 1 小時。\n\n在台北通裡報名只要三步驟、大約 1 分鐘：填姓名、填身分證字號（都可以直接從台北通帶入）、選一個時段。\n\n不會用手機也沒關係：按下面「需要別人協助填寫」，家人、里長或 1999 客服就會收到通知，陪您一起填。': 'Zhongshan District Health Center offers free health check-ups for elders aged 65 and over. The check-up takes about 1 hour.\n\nSigning up in TownPass takes just three steps and about 1 minute: enter your name, enter your ID number (both can be filled in directly from TownPass), and choose a time slot.\n\nNot comfortable with phones? That\'s fine. Tap "Need someone to help fill this in" below, and family, a village chief or 1999 hotline staff will get a notification and fill it in with you.',
    '正得里｜重陽敬老餐會報名': 'Zhengde Village | Double Ninth Festival Dinner Sign-up',
    '11 月 20 日中午 12 點，在正得里活動中心舉辦重陽敬老餐會，免費參加。名額 80 位，額滿為止，11/18 截止報名。\n\n可以選葷食或素食，需要的話里辦公處會派人去接您。': 'A Double Ninth Festival Dinner for seniors will be held on November 20 at 12:00 noon at the Zhengde Village Activity Center. Free to join. 80 places, first come, first served. Sign-up closes 11/18.\n\nYou can choose a regular or vegetarian meal. If needed, the village office will send someone to pick you up.',
    '長者流感疫苗｜線上預約接種時段': 'Senior Flu Vaccine | Book a Time Slot Online',
    '65 歲以上長輩免費接種流感疫苗。預約好時段，當天帶健保卡到中山區健康服務中心就可以，11/20 截止預約。': 'Free flu shots for elders aged 65 and over. Book a time slot, then bring your NHI card to Zhongshan District Health Center on the day. Booking closes 11/20.',
    '路燈與道路損壞｜隨手通報': 'Broken Streetlights and Roads | Quick Report',
    '發現路燈不亮、馬路有洞或人行道破損，都可以在這裡通報工務局，處理好之後會通知您。': 'If a streetlight is out, there is a hole in the road, or a sidewalk is damaged, you can report it to the Public Works Department here. You will be notified when it is fixed.',
