    '切換到': 'Chuyển sang',
    '切換後會結束目前的陪辦、清掉配對碼，並用同一個台北通帳號重新登入新的伺服器。選擇會記住，下次開啟 App 仍沿用。': 'Sau khi chuyển, lần hỗ trợ điền hiện tại sẽ kết thúc, mã ghép nối bị xóa, và đăng nhập lại vào máy chủ mới bằng cùng tài khoản TownPass. Lựa chọn sẽ được ghi nhớ, lần mở ứng dụng sau vẫn dùng như vậy.',
