    '另一位長輩': 'Một người cao tuổi khác',
    '只有您按「請長輩授權」後，長輩才能提供資料': 'Chỉ khi bạn nhấn “Nhờ người cao tuổi cho phép”, người cao tuổi mới có thể cung cấp thông tin',
    '只有您能換頁，長輩手機會顯示「會帶您到下一步」': 'Chỉ bạn mới chuyển trang được, điện thoại người cao tuổi sẽ hiện “Sẽ đưa bạn đến bước tiếp theo”',
    '只給您信得過的家人。對方掃了之後，您還要再按一次「加入」才算數。': 'Chỉ dành cho người nhà bạn tin tưởng. Sau khi họ quét, bạn còn phải nhấn “Tham gia” thêm một lần mới có hiệu lực.',
