    '在「請人陪我辦」按他，就能請他來幫忙。': 'Trong “Nhờ người hỗ trợ điền”, nhấn vào họ là có thể nhờ họ đến giúp.',
    '在長輩畫面上標示這一項': 'Đánh dấu mục này trên màn hình người cao tuổi',
    '在首頁按「掃描」掃長輩的配對 QR Code，會用這個身分開始陪辦。': 'Ở trang chủ nhấn “Quét” để quét mã QR ghép nối của người cao tuổi, sẽ dùng vai trò này để bắt đầu hỗ trợ điền.',
