    '完成': 'Hoàn tất',
    '完成一步自動到下一步，長輩也能按上一頁／下一頁': 'Xong một bước sẽ tự sang bước tiếp theo, người cao tuổi cũng có thể nhấn trang trước/trang sau',
    '客服接起來時，手機會跳出是誰要幫你，你按「同意」就開始。\n可以先關掉這個視窗繼續填。': 'Khi nhân viên nghe máy, điện thoại sẽ hiện ai muốn giúp bạn, bạn nhấn “Đồng ý” là bắt đầu.\nBạn có thể đóng cửa sổ này và điền tiếp.',
    '客服現在比較忙，請再試一次，或請旁邊的人幫忙。': 'Nhân viên đang khá bận, xin thử lại, hoặc nhờ người bên cạnh giúp.',
    '客服馬上來': 'Nhân viên đến ngay',
