    '對方不是好友': 'Người này không phải bạn bè',
    '對方在「請人陪我辦」看到的 6 位數號碼': 'Số 6 chữ số mà người kia thấy trong “Nhờ người hỗ trợ điền”',
    '對方在旁邊時最快': 'Nhanh nhất khi người kia ở bên cạnh',
    '對方會連上你的手機，一步一步陪你填。': 'Người kia sẽ kết nối với điện thoại của bạn và hướng dẫn bạn điền từng bước.',
    '對方用台北通掃描，或輸入下面的號碼，就能陪您一起辦。': 'Người kia dùng TownPass để quét, hoặc nhập số bên dưới, là có thể cùng bạn làm thủ tục.',
