    '您看不到長輩的個資。每一項資料都要長輩自己同意，最後也只有長輩能按送出。': 'Bạn không thấy thông tin cá nhân của người cao tuổi. Mỗi thông tin đều cần chính người cao tuổi đồng ý, và cuối cùng cũng chỉ người cao tuổi nhấn được nút gửi.',
