    '年滿 65 歲且設籍臺北市的長輩，可申請敬老卡，搭乘公車、捷運享有優惠。': 'Người cao tuổi từ đủ 65 tuổi và có hộ khẩu tại Đài Bắc có thể xin thẻ người cao tuổi, được ưu đãi khi đi xe buýt và tàu điện MRT.',
    '臺北市政府社會局': 'Sở Phúc lợi Xã hội Chính quyền thành phố Đài Bắc',
    '申辦說明': 'Giới thiệu thủ tục',
    '這次要幫您申請「敬老卡」。辦好之後，搭公車、捷運都有優惠。': 'Lần này sẽ giúp bạn xin “thẻ người cao tuổi”. Làm xong, đi xe buýt và tàu điện MRT đều được ưu đãi.',
    '先口頭確認長輩年滿 65 歲、戶籍在臺北市。確認後按「下一步」。': 'Hãy hỏi miệng để xác nhận người cao tuổi đủ 65 tuổi và có hộ khẩu tại Đài Bắc. Xác nhận xong nhấn “Bước tiếp theo”.',
    '確認身分': 'Xác nhận danh tính',
    '接下來需要您的基本資料。手機會一項一項問您，您同意才會提供。': 'Tiếp theo cần thông tin cơ bản của bạn. Điện thoại sẽ hỏi từng mục, bạn đồng ý thì mới cung cấp.',
    '依序按「請長輩授權」。請長輩自己看清楚手機畫面再按，不要替長輩按。': 'Lần lượt nhấn “Nhờ người cao tuổi cho phép”. Hãy để người cao tuổi tự xem kỹ màn hình điện thoại rồi mới nhấn, đừng nhấn thay.',
