    '身分證字號可以拿來辦很多事，請確認是您自己要申請': 'Số chứng minh có thể dùng để làm nhiều việc, hãy chắc chắn là chính bạn muốn xin',
    '市府人員不會要求您把身分證字號唸給陌生人聽': 'Nhân viên thành phố sẽ không yêu cầu bạn đọc số chứng minh cho người lạ nghe',
