    '按「請長輩確認送出」，長輩手機會顯示完整摘要。送出鍵只有長輩能按。': 'Nhấn “Nhờ người cao tuổi xác nhận gửi”, điện thoại người cao tuổi sẽ hiện bản tóm tắt đầy đủ. Nút gửi chỉ người cao tuổi nhấn được.',
