    '依各局處表單保存規定（Demo 示意）': 'Theo quy định lưu giữ biểu mẫu của từng sở ngành (minh họa Demo)',
    '表單說明': 'Giới thiệu biểu mẫu',
    '先跟長輩說明這份表單要做什麼，確認長輩想辦再按「下一步」。': 'Hãy nói trước với người cao tuổi biểu mẫu này để làm gì, xác nhận người cao tuổi muốn làm rồi mới nhấn “Bước tiếp theo”.',
    '這些資料可以從您的台北通帳號帶入，您同意才會提供。': 'Các thông tin này có thể lấy từ tài khoản TownPass của bạn, bạn đồng ý thì mới cung cấp.',
    '請長輩自己按同意，不要替長輩按。': 'Nhờ người cao tuổi tự nhấn đồng ý, đừng nhấn thay.',
    '回答問題': 'Trả lời câu hỏi',
    '請您自己在手機上回答。': 'Xin bạn tự trả lời trên điện thoại.',
    '把題目念給長輩聽，讓長輩自己在手機上回答。': 'Đọc câu hỏi cho người cao tuổi nghe, để người cao tuổi tự trả lời trên điện thoại.',
    '回答問題（1／2）': 'Trả lời câu hỏi (1/2)',
    '回答問題（2／2）': 'Trả lời câu hỏi (2/2)',
    '臺北市中山區健康服務中心辦理「長者流感疫苗預約」需要': 'Trung tâm Dịch vụ Sức khỏe quận Trung Sơn, thành phố Đài Bắc làm “Hẹn tiêm vắc-xin cúm cho người cao tuổi” cần',
    '電話': 'Điện thoại',
    '里長': 'Trưởng phường',
    '免費健康檢查｜65 歲以上長者報名': 'Khám sức khỏe miễn phí | Đăng ký cho người từ 65 tuổi',
    '中山區健康服務中心為 65 歲以上長輩提供免費健康檢查，檢查約 1 小時。\n\n在台北通裡報名只要三步驟、大約 1 分鐘：填姓名、填身分證字號（都可以直接從台北通帶入）、選一個時段。\n\n不會用手機也沒關係：按下面「需要別人協助填寫」，家人、里長或 1999 客服就會收到通知，陪您一起填。': 'Trung tâm Dịch vụ Sức khỏe quận Trung Sơn cung cấp khám sức khỏe miễn phí cho người cao tuổi từ 65 tuổi, khám khoảng 1 giờ.\n\nĐăng ký trong TownPass chỉ ba bước, khoảng 1 phút: điền họ tên, điền số chứng minh (đều có thể lấy thẳng từ TownPass), chọn một khung giờ.\n\nKhông biết dùng điện thoại cũng không sao: nhấn “Cần người khác hỗ trợ điền” bên dưới, người nhà, trưởng phường hoặc nhân viên 1999 sẽ nhận được thông báo và cùng bạn điền.',
    '正得里｜重陽敬老餐會報名': 'Phường Chính Đắc | Đăng ký tiệc mừng Tết Trùng Dương',
    '11 月 20 日中午 12 點，在正得里活動中心舉辦重陽敬老餐會，免費參加。名額 80 位，額滿為止，11/18 截止報名。\n\n可以選葷食或素食，需要的話里辦公處會派人去接您。': '12 giờ trưa ngày 20 tháng 11, tại trung tâm sinh hoạt phường Chính Đắc có tiệc mừng Tết Trùng Dương, miễn phí tham gia. Có 80 chỗ, hết chỗ là dừng, hạn đăng ký 18/11.\n\nCó thể chọn món mặn hoặc chay, nếu cần văn phòng phường sẽ cử người đến đón bạn.',
    '長者流感疫苗｜線上預約接種時段': 'Vắc-xin cúm cho người cao tuổi | Hẹn khung giờ tiêm trực tuyến',
    '65 歲以上長輩免費接種流感疫苗。預約好時段，當天帶健保卡到中山區健康服務中心就可以，11/20 截止預約。': 'Người từ 65 tuổi trở lên được tiêm vắc-xin cúm miễn phí. Hẹn xong khung giờ, hôm đó mang thẻ bảo hiểm y tế đến Trung tâm Dịch vụ Sức khỏe quận Trung Sơn là được, hạn hẹn 20/11.',
    '路燈與道路損壞｜隨手通報': 'Đèn đường và đường hư hỏng | Báo nhanh',
    '發現路燈不亮、馬路有洞或人行道破損，都可以在這裡通報工務局，處理好之後會通知您。': 'Nếu thấy đèn đường không sáng, đường có ổ gà hoặc vỉa hè hư hỏng, đều có thể báo cho Sở Công vụ tại đây, xử lý xong sẽ báo cho bạn.',
  },
