    '臺北市中山區健康服務中心辦理「長者流感疫苗預約」需要': 'Pusat Layanan Kesehatan Distrik Zhongshan, Kota Taipei membutuhkan ini untuk “Reservasi Vaksin Flu untuk Lansia”',
    '電話': 'Telepon',
    '里長': 'Kepala kelurahan',
    '免費健康檢查｜65 歲以上長者報名': 'Pemeriksaan Kesehatan Gratis｜Pendaftaran untuk Lansia 65 Tahun ke Atas',
    '中山區健康服務中心為 65 歲以上長輩提供免費健康檢查，檢查約 1 小時。\n\n在台北通裡報名只要三步驟、大約 1 分鐘：填姓名、填身分證字號（都可以直接從台北通帶入）、選一個時段。\n\n不會用手機也沒關係：按下面「需要別人協助填寫」，家人、里長或 1999 客服就會收到通知，陪您一起填。': 'Pusat Layanan Kesehatan Distrik Zhongshan menyediakan pemeriksaan kesehatan gratis untuk lansia 65 tahun ke atas, pemeriksaan sekitar 1 jam.\n\nMendaftar lewat TownPass hanya tiga langkah, sekitar 1 menit: isi nama, isi nomor KTP/ID (keduanya bisa langsung diambil dari TownPass), dan pilih satu jadwal.\n\nTidak bisa memakai ponsel juga tidak apa-apa: ketuk “Perlu bantuan orang lain untuk mengisi” di bawah, lalu keluarga, kepala kelurahan, atau petugas 1999 akan menerima pemberitahuan dan menemani Anda mengisi.',
    '正得里｜重陽敬老餐會報名': 'Kelurahan Zhengde｜Pendaftaran Makan Bersama Lansia Chung Yang',
    '11 月 20 日中午 12 點，在正得里活動中心舉辦重陽敬老餐會，免費參加。名額 80 位，額滿為止，11/18 截止報名。\n\n可以選葷食或素食，需要的話里辦公處會派人去接您。': '20 November pukul 12 siang, Makan Bersama Lansia Chung Yang diadakan di Pusat Kegiatan Kelurahan Zhengde, gratis. Tersedia 80 tempat, sampai penuh, pendaftaran ditutup 18/11.\n\nBisa memilih makanan non-vegetarian atau vegetarian, dan jika perlu, kantor kelurahan akan mengirim orang untuk menjemput Anda.',
    '長者流感疫苗｜線上預約接種時段': 'Vaksin Flu Lansia｜Reservasi Jadwal Vaksinasi Online',
    '65 歲以上長輩免費接種流感疫苗。預約好時段，當天帶健保卡到中山區健康服務中心就可以，11/20 截止預約。': 'Lansia 65 tahun ke atas mendapat vaksin flu gratis. Setelah jadwal direservasi, cukup datang ke Pusat Layanan Kesehatan Distrik Zhongshan dengan membawa kartu asuransi kesehatan (NHI), reservasi ditutup 20/11.',
    '路燈與道路損壞｜隨手通報': 'Lampu Jalan dan Kerusakan Jalan｜Lapor dengan Mudah',
    '發現路燈不亮、馬路有洞或人行道破損，都可以在這裡通報工務局，處理好之後會通知您。': 'Jika lampu jalan mati, jalan berlubang, atau trotoar rusak, Anda bisa melaporkannya di sini kepada Dinas Pekerjaan Umum, dan Anda akan diberi tahu setelah selesai ditangani.',
