    '收到了，謝謝你！我們會盡快派人去看。': 'ได้รับแล้ว ขอบคุณ! เราจะส่งคนไปดูโดยเร็ว',
    '線上表單': 'แบบฟอร์มออนไลน์',
    '依各局處表單保存規定（Demo 示意）': 'ตามระเบียบการเก็บแบบฟอร์มของแต่ละหน่วยงาน (ตัวอย่างเดโม)',
    '表單說明': 'คำอธิบายแบบฟอร์ม',
    '先跟長輩說明這份表單要做什麼，確認長輩想辦再按「下一步」。': 'อธิบายให้ผู้สูงอายุฟังก่อนว่าแบบฟอร์มนี้ทำอะไร ยืนยันว่าผู้สูงอายุอยากทำแล้วกด「ขั้นตอนถัดไป」',
    '這些資料可以從您的台北通帳號帶入，您同意才會提供。': 'ข้อมูลเหล่านี้ดึงจากบัญชี TownPass ของคุณได้ ต้องได้รับความยินยอมจากคุณจึงจะให้',
    '請長輩自己按同意，不要替長輩按。': 'ให้ผู้สูงอายุกดยินยอมเอง อย่ากดแทนผู้สูงอายุ',
    '回答問題': 'ตอบคำถาม',
    '請您自己在手機上回答。': 'กรุณาตอบเองบนมือถือ',
    '把題目念給長輩聽，讓長輩自己在手機上回答。': 'อ่านคำถามให้ผู้สูงอายุฟัง แล้วให้ผู้สูงอายุตอบเองบนมือถือ',
    '回答問題（1／2）': 'ตอบคำถาม (1/2)',
    '回答問題（2／2）': 'ตอบคำถาม (2/2)',
    '臺北市中山區健康服務中心辦理「長者流感疫苗預約」需要': 'การดำเนินการ「จองฉีดวัคซีนไข้หวัดใหญ่สำหรับผู้สูงอายุ」ของศูนย์บริการสุขภาพเขตจงซาน นครไทเป ต้องใช้',
    '電話': 'เบอร์โทร',
    '里長': 'ผู้ใหญ่บ้าน',
    '免費健康檢查｜65 歲以上長者報名': 'ตรวจสุขภาพฟรี｜สมัครสำหรับผู้สูงอายุ 65 ปีขึ้นไป',
    '中山區健康服務中心為 65 歲以上長輩提供免費健康檢查，檢查約 1 小時。\n\n在台北通裡報名只要三步驟、大約 1 分鐘：填姓名、填身分證字號（都可以直接從台北通帶入）、選一個時段。\n\n不會用手機也沒關係：按下面「需要別人協助填寫」，家人、里長或 1999 客服就會收到通知，陪您一起填。': 'ศูนย์บริการสุขภาพเขตจงซานให้ผู้สูงอายุอายุ 65 ปีขึ้นไปตรวจสุขภาพฟรี ตรวจประมาณ 1 ชั่วโมง\n\nสมัครใน TownPass ทำแค่สามขั้นตอน ประมาณ 1 นาที: กรอกชื่อ กรอกเลขประจำตัว (ดึงมาจาก TownPass ได้โดยตรงทั้งสองอย่าง) เลือกช่วงเวลา\n\nใช้มือถือไม่เป็นก็ไม่เป็นไร: กด「ต้องการให้คนอื่นช่วยกรอก」ด้านล่าง ครอบครัว ผู้ใหญ่บ้าน หรือเจ้าหน้าที่ 1999 จะได้รับแจ้งเตือนและช่วยคุณกรอก',
    '正得里｜重陽敬老餐會報名': 'หมู่บ้านเจิ้งเต๋อ｜สมัครงานเลี้ยงวันผู้สูงอายุ (ฉงหยาง)',
    '11 月 20 日中午 12 點，在正得里活動中心舉辦重陽敬老餐會，免費參加。名額 80 位，額滿為止，11/18 截止報名。\n\n可以選葷食或素食，需要的話里辦公處會派人去接您。': 'วันที่ 20 พฤศจิกายน เที่ยง 12 นาฬิกา ที่ศูนย์กิจกรรมหมู่บ้านเจิ้งเต๋อ จัดงานเลี้ยงวันผู้สูงอายุ (ฉงหยาง) เข้าร่วมฟรี จำนวน 80 ท่าน เต็มแล้วปิดรับ ปิดรับสมัครวันที่ 18/11\n\nเลือกอาหารทั่วไปหรืออาหารมังสวิรัติได้ ถ้าต้องการ สำนักงานหมู่บ้านจะส่งคนไปรับคุณ',
    '長者流感疫苗｜線上預約接種時段': 'วัคซีนไข้หวัดใหญ่สำหรับผู้สูงอายุ｜จองช่วงเวลาฉีดออนไลน์',
    '65 歲以上長輩免費接種流感疫苗。預約好時段，當天帶健保卡到中山區健康服務中心就可以，11/20 截止預約。': 'ผู้สูงอายุอายุ 65 ปีขึ้นไปฉีดวัคซีนไข้หวัดใหญ่ฟรี จองช่วงเวลาแล้ว วันนัดนำบัตรประกันสุขภาพไปที่ศูนย์บริการสุขภาพเขตจงซานได้เลย ปิดรับจองวันที่ 20/11',
    '路燈與道路損壞｜隨手通報': 'แจ้งไฟถนนและถนนชำรุด｜แจ้งได้ง่ายๆ',
    '發現路燈不亮、馬路有洞或人行道破損，都可以在這裡通報工務局，處理好之後會通知您。': 'พบไฟถนนไม่ติด ถนนเป็นหลุม หรือทางเท้าชำรุด แจ้งสำนักโยธาธิการได้ที่นี่ เมื่อดำเนินการเสร็จจะแจ้งให้คุณทราบ',
  },
