    '中山區健康服務中心為 65 歲以上長輩提供免費健康檢查，檢查約 1 小時。\n\n在台北通裡報名只要三步驟、大約 1 分鐘：填姓名、填身分證字號（都可以直接從台北通帶入）、選一個時段。\n\n不會用手機也沒關係：按下面「需要別人協助填寫」，家人、里長或 1999 客服就會收到通知，陪您一起填。': '台北市中山区健康サービスセンターでは、65 歳以上の高齢者に無料の健康診断を提供しています。検査は約 1 時間です。\n\nTownPass なら 3 ステップ、約 1 分で申し込めます：氏名、身分証番号（どちらも TownPass からそのまま入力できます）を入力し、時間帯を 1 つ選びます。\n\nスマートフォンが苦手でも大丈夫です。下の「入力を手伝ってもらう」を押すと、家族、里長（地区長）、1999 窓口に通知が届き、一緒に入力してもらえます。',
    '正得里｜重陽敬老餐會報名': '正得里｜重陽敬老会食の申し込み',
    '11 月 20 日中午 12 點，在正得里活動中心舉辦重陽敬老餐會，免費參加。名額 80 位，額滿為止，11/18 截止報名。\n\n可以選葷食或素食，需要的話里辦公處會派人去接您。': '11 月 20 日 12 時、正得里活動センターで重陽敬老会食を開催します。参加無料。定員 80 名、先着順で、11/18 が申し込み締め切りです。\n\n通常食かベジタリアン食を選べます。必要な場合は、里事務所の担当者がお迎えに伺います。',
    '長者流感疫苗｜線上預約接種時段': '高齢者インフルエンザワクチン｜接種時間帯のオンライン予約',
    '65 歲以上長輩免費接種流感疫苗。預約好時段，當天帶健保卡到中山區健康服務中心就可以，11/20 截止預約。': '65 歳以上の高齢者は、インフルエンザワクチンを無料で接種できます。時間帯を予約し、当日は健康保険証を持って中山区健康サービスセンターへお越しください。予約の締め切りは 11/20 です。',
    '路燈與道路損壞｜隨手通報': '街灯・道路破損｜かんたん通報',
    '發現路燈不亮、馬路有洞或人行道破損，都可以在這裡通報工務局，處理好之後會通知您。': '街灯が点かない、道路に穴がある、歩道が壊れているなどを見つけたら、ここで工務局に通報できます。対応が済んだらお知らせします。',
  },
