    '客服接起來時，手機會跳出是誰要幫你，你按「同意」就開始。\n可以先關掉這個視窗繼續填。': '상담원이 받으면 누가 도와주는지 휴대폰에 표시돼요. 「동의」를 누르면 시작해요.\n이 창을 닫고 계속 작성해도 돼요.',
