    '社會福利': '사회복지',
    '年滿 65 歲且設籍臺北市的長輩，可申請敬老卡，搭乘公車、捷運享有優惠。': '만 65세 이상이고 타이베이시에 주소를 둔 어르신은 경로카드를 신청해 버스와 지하철 할인을 받을 수 있어요.',
