    '申辦說明': '신청 안내',
    '這次要幫您申請「敬老卡」。辦好之後，搭公車、捷運都有優惠。': '이번에 「경로카드」 신청을 도와드려요. 발급되면 버스와 지하철에서 할인을 받아요.',
    '先口頭確認長輩年滿 65 歲、戶籍在臺北市。確認後按「下一步」。': '어르신이 만 65세 이상이고 타이베이시에 주소가 있는지 먼저 말로 확인하세요. 확인했으면 「다음 단계」를 누르세요.',
    '確認身分': '신분 확인',
    '接下來需要您的基本資料。手機會一項一項問您，您同意才會提供。': '이제 기본 정보가 필요해요. 휴대폰이 하나씩 물어보고, 동의하셔야 제공돼요.',
    '依序按「請長輩授權」。請長輩自己看清楚手機畫面再按，不要替長輩按。': '순서대로 「어르신에게 권한 요청」을 누르세요. 어르신이 휴대폰 화면을 잘 보고 직접 누르게 하고, 대신 누르지 마세요.',
    '姓名': '이름',
    '確認申請人是您本人': '신청인이 본인인지 확인해요',
    '姓名會印在敬老卡上': '이름은 경로카드에 인쇄돼요',
    '申辦完成後保存 5 年（Demo 示意）': '신청 완료 후 5년간 보관 (데모 예시)',
