    '確認您已年滿 65 歲': '만 65세 이상인지 확인해요',
    '出生日期常被拿來核對身分，請只提供給您信任的申請': '생년월일은 신분 확인에 자주 쓰여요. 믿을 수 있는 신청에만 제공하세요',
    '身分證字號': '신분증 번호',
    '核對戶籍與申請資格，避免重複申請': '주소지와 신청 자격을 확인하고 중복 신청을 막아요',
    '身分證字號可以拿來辦很多事，請確認是您自己要申請': '신분증 번호는 여러 업무에 쓸 수 있어요. 본인이 신청하는 것인지 확인하세요',
    '市府人員不會要求您把身分證字號唸給陌生人聽': '시청 직원은 모르는 사람에게 신분증 번호를 불러 달라고 하지 않아요',
    '地址與電話': '주소와 전화번호',
