    '按「請長輩確認送出」，長輩手機會顯示完整摘要。送出鍵只有長輩能按。': '「어르신에게 제출 확인 요청」을 누르면 어르신 휴대폰에 전체 요약이 표시돼요. 제출 버튼은 어르신만 누를 수 있어요.',
