    '線上表單': '온라인 신청서',
    '依各局處表單保存規定（Demo 示意）': '각 부서 신청서 보관 규정에 따라 (데모 예시)',
    '表單說明': '신청서 안내',
    '先跟長輩說明這份表單要做什麼，確認長輩想辦再按「下一步」。': '이 신청서가 무엇인지 어르신께 먼저 설명하고, 신청하고 싶은지 확인한 뒤 「다음 단계」를 누르세요.',
    '這些資料可以從您的台北通帳號帶入，您同意才會提供。': '이 정보는 TownPass 계정에서 가져올 수 있고, 동의하셔야 제공돼요.',
    '請長輩自己按同意，不要替長輩按。': '어르신이 직접 동의를 누르게 하고, 대신 누르지 마세요.',
    '回答問題': '질문에 답하기',
    '請您自己在手機上回答。': '직접 휴대폰에서 답해 주세요.',
    '把題目念給長輩聽，讓長輩自己在手機上回答。': '질문을 어르신께 읽어 드리고, 어르신이 휴대폰에서 직접 답하게 하세요.',
    '回答問題（1／2）': '질문에 답하기 (1/2)',
    '回答問題（2／2）': '질문에 답하기 (2/2)',
    '臺北市中山區健康服務中心辦理「長者流感疫苗預約」需要': '타이베이시 중산구 건강서비스센터가 「어르신 독감 예방접종 예약」을 처리하려면 필요해요',
    '電話': '전화번호',
    '里長': '이장',
    '免費健康檢查｜65 歲以上長者報名': '무료 건강검진｜65세 이상 어르신 신청',
    '中山區健康服務中心為 65 歲以上長輩提供免費健康檢查，檢查約 1 小時。\n\n在台北通裡報名只要三步驟、大約 1 分鐘：填姓名、填身分證字號（都可以直接從台北通帶入）、選一個時段。\n\n不會用手機也沒關係：按下面「需要別人協助填寫」，家人、里長或 1999 客服就會收到通知，陪您一起填。': '중산구 건강서비스센터가 65세 이상 어르신께 무료 건강검진을 제공해요. 검진은 약 1시간 걸려요.\n\nTownPass에서는 이름 작성, 신분증 번호 작성(둘 다 TownPass에서 바로 가져올 수 있어요), 시간대 선택, 세 단계로 약 1분이면 신청해요.\n\n휴대폰이 어려워도 괜찮아요. 아래 「다른 사람의 도움이 필요해요」를 누르면 가족, 이장님, 1999 상담원에게 알림이 가서 함께 작성해 드려요.',
    '正得里｜重陽敬老餐會報名': '정더리｜중양절 경로 식사 모임 신청',
    '11 月 20 日中午 12 點，在正得里活動中心舉辦重陽敬老餐會，免費參加。名額 80 位，額滿為止，11/18 截止報名。\n\n可以選葷食或素食，需要的話里辦公處會派人去接您。': '11월 20일 낮 12시, 정더리 활동센터에서 중양절 경로 식사 모임을 열어요. 무료로 참가해요. 80명 선착순으로 마감되고, 11/18까지 신청받아요.\n\n일반식이나 채식을 고를 수 있고, 필요하면 리 사무소에서 데리러 가요.',
    '長者流感疫苗｜線上預約接種時段': '어르신 독감 예방접종｜온라인 시간대 예약',
    '65 歲以上長輩免費接種流感疫苗。預約好時段，當天帶健保卡到中山區健康服務中心就可以，11/20 截止預約。': '65세 이상 어르신은 독감 예방접종이 무료예요. 시간대를 예약하고 당일 건강보험증을 가져와 중산구 건강서비스센터로 오시면 돼요. 예약은 11/20까지예요.',
    '路燈與道路損壞｜隨手通報': '가로등 및 도로 파손｜간편 신고',
    '發現路燈不亮、馬路有洞或人行道破損，都可以在這裡通報工務局，處理好之後會通知您。': '가로등이 꺼졌거나 도로에 구멍이 있거나 인도가 파손되었다면 여기에서 공무국에 신고하세요. 처리되면 알려 드려요.',
  },
};
